/** Full Marketplace page: orange content, silver curved rails, category list and feature panel. */
final class IptvBrowser extends View {
  IptvGuide guide;
  final MainActivity a;final IptvClient ra;final Paint p=new Paint(3);final ArrayList<Item> rows=new ArrayList<>();
  int screen,index,offset;float scale=1,left,height=720,down;long stick;String heading="IPTV";JSONObject detail;boolean closed;
  static class Item{String title,sub,body,image;Runnable run;Item(String t,String s,String b,String i,Runnable r){title=t;sub=s;body=b;image=i;run=r;}}
  IptvBrowser(MainActivity a){super(a);this.a=a;ra=a.iptv;setFocusableInTouchMode(true);ra.changed=()->{int selected=index,scroll=offset;build();index=Math.min(selected,Math.max(0,rows.size()-1));offset=Math.min(scroll,Math.max(0,rows.size()-slots()));if(guide!=null)guide.reload();invalidate();};home();}
  void add(String title,String sub,String body,String image,Runnable run){rows.add(new Item(title,sub,body,image,run));}
  void home(){screen=0;index=offset=0;build();invalidate();}
  void page(int n){screen=n;index=offset=0;build();if(n==5&&channel!=null){ArrayList<IptvData.Programme> list=ra.guide(channel);for(int i=0;i<list.size();i++)if(list.get(i).end>System.currentTimeMillis()){index=i;offset=Math.max(0,index-1);break;}}invalidate();}
  String filter="",query="";int listMode;IptvData.Channel channel;IptvData.Programme programme;IptvPlayer player;ArrayList<IptvData.Channel> visible=new ArrayList<>();
  void build(){rows.clear();
    if(screen==0){heading="IPTV";add("TV Guide","Live preview and programme timeline","Browse all visible channels by time. Preview uses one connection and stops before full-screen playback.","",this::openGuide);add("All Channels",ra.visibleChannels().size()+" visible channels","Browse every channel in your M3U playlist.","",()->{listMode=0;filter=query="";page(2);});add("Channel Groups","Browse categories","Groups supplied by your playlist.","",()->page(1));add("Favorites","Your saved channels","Favorite a channel from its options.","",()->{listMode=1;filter=query="";page(2);});add("Recently Watched","Last 50 channels","Return to a recently watched channel.","",()->{listMode=2;filter=query="";page(2);});add("Search Channels",query,"Search channel names and groups.","",()->edit("Search Channels",query,false,v->{query=v;filter="";listMode=0;page(2);}));add("Refresh Playlist / Guide","",ra.status,"",ra::refresh);add("Settings","Playlist and XMLTV sources","Add your playlist URL or import a local file.","",()->page(4));}
    else if(screen==1){heading="Channel Groups";TreeMap<String,Integer> groups=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);for(IptvData.Channel c:ra.visibleChannels())groups.put(c.group,groups.getOrDefault(c.group,0)+1);for(String group:groups.keySet())add(group,groups.get(group)+" channels","Browse this channel group.","",()->{filter=group;query="";listMode=0;page(2);});if(rows.isEmpty())add("No channel groups","Add a playlist",ra.status,"",()->page(4));}
    else if(screen==2){heading=listMode==1?"Favorites":listMode==2?"Recently Watched":!query.isEmpty()?"Search: "+query:filter.isEmpty()?"All Channels":filter;visible.clear();for(IptvData.Channel c:ra.visibleChannels())if((filter.isEmpty()||filter.equals(c.group))&&(query.isEmpty()||(c.name+" "+c.group).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))&&(listMode!=1||ra.favorite(c)))visible.add(c);if(listMode==2){ArrayList<String> ids=new ArrayList<>();try{JSONArray list=new JSONArray(ra.prefs.getString("recent","[]"));for(int i=0;i<list.length();i++)ids.add(list.optString(i));}catch(Exception ignored){}visible.removeIf(c->!ids.contains(c.id));visible.sort(Comparator.comparingInt(c->ids.indexOf(c.id)));}for(IptvData.Channel c:visible){IptvData.Programme now=ra.now(c);add((ra.favorite(c)?"★ ":"")+c.name,now==null?c.group:now.title,description(c),c.logo,()->{channel=c;page(3);});}if(rows.isEmpty())add("No channels to show","",ra.status,"",()->page(4));}
    else if(screen==3&&channel!=null){heading=channel.name;add("Watch Live",channel.group,description(channel),channel.logo,()->play(channel,null));add("Programme Guide","Now, next and catch-up","Browse available XMLTV programmes. Catch-up requires a compatible catchup-source supplied by your provider.",channel.logo,()->page(5));add(ra.favorite(channel)?"Remove Favorite":"Add Favorite","",description(channel),channel.logo,()->ra.favoriteToggle(channel));add("Stream format: "+format(channel),"Select to change","Auto detects common stream URLs. Choose HLS for an extensionless HLS URL, or MPEG-TS for a transport stream.",channel.logo,()->{ra.prefs.edit().putInt("format_"+channel.id,(ra.prefs.getInt("format_"+channel.id,0)+1)%3).apply();build();invalidate();});}
    else if(screen==5&&channel!=null){heading=channel.name+" · Guide";long now=System.currentTimeMillis();ArrayList<IptvData.Programme> list=ra.guide(channel);for(IptvData.Programme p:list){String tag=p.start<=now&&p.end>now?"On now":p.end<=now?"Earlier":"Upcoming";add(time(p.start)+"  "+p.title,tag,p.description,channel.logo,()->{programme=p;page(6);});}if(rows.isEmpty())add("No guide data","Add or refresh XMLTV","Guide matching uses the playlist's tvg-id and XMLTV channel ID.",channel.logo,()->page(4));}
    else if(screen==6&&programme!=null){heading=programme.title;String catchup=IptvData.catchup(channel,programme,System.currentTimeMillis());boolean now=programme.start<=System.currentTimeMillis()&&programme.end>System.currentTimeMillis();add(now?"Watch Live":catchup.isEmpty()?"Programme Information":"Watch Catch-up",time(programme.start)+" – "+time(programme.end),programme.description,channel.logo,()->{if(now)play(channel,null);else if(!catchup.isEmpty())play(channel,catchup);});if(!now&&catchup.isEmpty())add("Catch-up unavailable","","This programme is upcoming or outside your provider's supported catch-up window.",channel.logo,()->{});}
    else if(screen==7){heading="Languages / Countries";add("Show All","Reset visibility","No channels are deleted. Labels are detected from metadata and channel/group prefixes.","",ra::showAllLabels);TreeMap<String,Integer> counts=ra.labelCounts();Set<String> hidden=ra.prefs.getStringSet("hidden_labels",Collections.emptySet());for(String code:counts.keySet())add((hidden.contains(code)?"Hidden · ":"Shown · ")+IptvLabels.label(code),counts.get(code)+" channels · A to toggle","Hide any matching label to hide the channel. EN is English; US is United States. Unlabelled channels remain visible unless you hide them explicitly.","",()->ra.toggleLabel(code));if(counts.isEmpty())add("Import a playlist first","Labels appear automatically","Your provider's detected labels will be listed here after import.","",()->page(4));}
    else if(screen==4){heading="IPTV Settings";add("Languages / Countries",ra.prefs.getStringSet("hidden_labels",Collections.emptySet()).size()+" labels hidden","Show or hide channels by playlist language, country, and label prefixes. Filters apply to the guide, groups, search, favorites, recent channels and channel switching.","",()->page(7));add("M3U Playlist URL",ra.source().isEmpty()?"Not set":"Saved privately","Enter your provider's complete playlist URL. Source addresses are encrypted and hidden here.","",()->edit("M3U Playlist URL","",true,v->ra.set("playlist",v)));add("Paste Playlist URL","Device clipboard","Read clipboard only when selected.","",()->paste("playlist"));add("Import M3U File","Choose a local playlist","Supports M3U and M3U8 channel lists.","",()->ra.choose(false));add("XMLTV Guide URL",ra.guideSource().isEmpty()?"Not set":"Saved privately","Supports XMLTV and gzip-compressed XMLTV. A playlist-provided guide URL is used when available.","",()->edit("XMLTV Guide URL","",true,v->ra.set("guide",v)));add("Paste Guide URL","Device clipboard","Read clipboard only when selected.","",()->paste("guide"));add("Import XMLTV File","Local XML or XML.GZ","Choose your guide file.","",()->ra.choose(true));add("Refresh Programme Guide","",ra.status,"",ra::refreshGuide);add("Buffer: "+new String[]{"Fast","Balanced","Stable"}[ra.prefs.getInt("buffer",1)],"Select to change","Changes take effect on the next stream. Stable buffers more data for unreliable connections.","",()->{ra.prefs.edit().putInt("buffer",(ra.prefs.getInt("buffer",1)+1)%3).apply();build();invalidate();});add("Reconnect: "+ra.prefs.getInt("retries",3)+" attempts","Select to change","Automatic retry after a stream error. Manual retry is available in the player.","",()->{ra.prefs.edit().putInt("retries",(ra.prefs.getInt("retries",3)+3)%9).apply();build();invalidate();});}
  }
  void openGuide(){if(guide!=null)return;guide=new IptvGuide(this);a.addContentView(guide,new ViewGroup.LayoutParams(-1,-1));guide.requestFocus();}
  void playerClosed(){if(guide!=null){guide.setVisibility(VISIBLE);guide.requestFocus();guide.invalidate();}else requestFocus();}
  String format(IptvData.Channel c){return new String[]{"Auto","HLS","MPEG-TS"}[ra.prefs.getInt("format_"+c.id,0)];}
  String time(long t){return new java.text.SimpleDateFormat("EEE HH:mm",Locale.getDefault()).format(new java.util.Date(t));}
  String description(IptvData.Channel c){IptvData.Programme now=ra.now(c);String text=c.group;if(now!=null)text+="\n\nNow: "+now.title+"\n"+time(now.start)+" – "+time(now.end)+"\n\n"+now.description;else text+="\n\nNo current programme data.";return text;}
  void play(IptvData.Channel c,String catchup){a.media.pauseMusic();ra.recent(c);player=new IptvPlayer(this,c,catchup);a.addContentView(player,new ViewGroup.LayoutParams(-1,-1));player.requestFocus();}
  void edit(String title,String initial,boolean secret,java.util.function.Consumer<String> save){boolean wasSecure=(a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0;if(secret)a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);a.tools.editor=new BladesKeyboard(a,title,initial,4096,false,v->{save.accept(v);build();invalidate();},()->{a.tools.editor=null;if(secret&&!wasSecure)a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);post(this::requestFocus);});a.tools.editor.secret=secret;}
  void paste(String key){android.content.ClipboardManager cb=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);ClipData clip=cb.getPrimaryClip();if(clip!=null&&clip.getItemCount()>0&&clip.getItemAt(0).getText()!=null)ra.set(key,clip.getItemAt(0).getText().toString());}
  void back(){if(player!=null){player.close();return;}if(guide!=null){guide.close();return;}if(screen==7)page(4);else if(screen==0)close(true);else if(screen==6)page(5);else if(screen==5)page(3);else if(screen==3)page(2);else home();}
  void close(boolean hub){closed=true;if(guide!=null)guide.close();ra.changed=()->{};if(player!=null)player.close();if(getParent() instanceof ViewGroup)((ViewGroup)getParent()).removeView(this);a.iptvBrowser=null;if(hub)a.openJellyfin();else a.dashboard.requestFocus();}
  int slots(){return Math.max(3,Math.min(9,(int)((height-300)/61)));}
  void move(int n){index=Math.max(0,Math.min(rows.size()-1,index+n));if(index<offset)offset=index;if(index>=offset+slots())offset=index-slots()+1;invalidate();}
  void select(){if(index>=0&&index<rows.size())rows.get(index).run.run();invalidate();}
  @Override public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0&&(key==96||key==97))return true;switch(key){case 19:move(-1);break;case 20:move(1);break;case 102:move(-slots());break;case 103:move(slots());break;case 96:case 66:case 23:select();break;case 97:case 4:back();break;case 99:page(4);break;case 100:ra.refresh();break;}return true;}
  @Override public boolean onKeyUp(int key,KeyEvent e){return true;}
  @Override public boolean onGenericMotionEvent(MotionEvent e){float y=e.getAxisValue(16);if(Math.abs(y)<.5f)y=e.getAxisValue(1);long now=android.os.SystemClock.uptimeMillis();if(Math.abs(y)<.5f){stick=0;return true;}if(now-stick>180){move(y>0?1:-1);stick=now;}return true;}
  void text(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(a.dashboard.regular);p.setTextSize(size);c.drawText(s,x,y,p);}
  String fit(String s,float width,float size){p.setTypeface(a.dashboard.regular);p.setTextSize(size);if(p.measureText(s)<=width)return s;int n=s.length();while(n>0&&p.measureText(s.substring(0,n)+"…")>width)n--;return s.substring(0,n)+"…";}
  void gradient(Canvas c,RectF r,int top,int bottom,float radius){p.setShader(new LinearGradient(r.left,r.top,r.left,r.bottom,top,bottom,Shader.TileMode.CLAMP));c.drawRoundRect(r,radius,radius,p);p.setShader(null);}
  void button(Canvas c,float x,float y,String letter,String label,int color){p.setShader(new RadialGradient(x-4,y-5,17,new int[]{0xfff5f7de,color,0xff60543b},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,15,p);p.setShader(null);text(c,letter,x-8,y+8,23,Color.WHITE);text(c,label,x+24,y+8,24,0xfffff9e9);}
  void wrapped(Canvas c,String s,float x,float y,float width,float size,float bottom){for(String paragraph:s.split("\n",-1)){String line="";for(String word:paragraph.split(" ")){p.setTextSize(size);if(p.measureText(line+" "+word)>width&&!line.isEmpty()){if(y>bottom)return;text(c,line,x,y,size,0xff17344e);y+=size+6;line=word;}else line=line.isEmpty()?word:line+" "+word;}if(y>bottom)return;text(c,line,x,y,size,0xff17344e);y+=size+6;}}
  @Override protected void onDraw(Canvas c){scale=Math.min(getWidth()/1280f,getHeight()/720f);height=getHeight()/scale;left=(getWidth()-1280*scale)/2;c.drawColor(0xff87908c);c.save();c.translate(left,0);c.scale(scale,scale);
    gradient(c,new RectF(88,0,1195,height),0xff5688b8,0xffc8e0eb,0);
    for(int side=0;side<2;side++){c.save();if(side==1){c.translate(1280,0);c.scale(-1,1);}Path rail=new Path();rail.moveTo(0,0);rail.lineTo(92,0);rail.cubicTo(83,50,78,91,96,110);rail.cubicTo(112,125,104,height*.7f,90,height*.8f);rail.cubicTo(73,height*.9f,81,height*.96f,85,height);rail.lineTo(0,height);rail.close();c.clipPath(rail);p.setShader(new LinearGradient(0,0,110,0,new int[]{0xff465665,0xffe9eff5,0xff9baaba,0xffe3eaf0,0xff475665},null,Shader.TileMode.CLAMP));c.drawRect(0,0,120,height,p);p.setShader(null);c.restore();}
    c.save();c.translate(48,135);c.rotate(90);text(c,"media",0,0,25,0xff27323d);c.restore();c.save();c.translate(1225,135);c.rotate(90);text(c,"media center",0,0,25,0xff27323d);c.restore();
    gradient(c,new RectF(100,-20,1180,96),0xff152f59,0xff315e9e,28);text(c,"Media Center",128,60,38,0xfff0f7ff);text(c,"IPTV",1000,58,28,0xffdceaf5);
    text(c,fit(heading,1000,30),130,145,30,0xff17344e);text(c,fit(ra.channels.size()+" channels · "+ra.programmes.size()+" guide entries",1000,22),130,181,22,0xff284e6b);
    for(int i=offset;i<Math.min(rows.size(),offset+slots());i++){float y=215+(i-offset)*61;Item item=rows.get(i);if(i==index)gradient(c,new RectF(123,y-2,669,y+56),0xffe8f5fa,0xff9cc5df,10);text(c,fit(item.title,500,25),140,y+25,25,0xff17344e);text(c,fit(item.sub,500,18),140,y+48,18,0xff315772);p.setColor(0x55496c85);c.drawLine(132,y+59,662,y+59,p);}
    if(offset>0)text(c,"▲",638,205,20,0xff315772);if(offset+slots()<rows.size())text(c,"▼",638,220+slots()*61,20,0xff315772);
    if(!rows.isEmpty()){Item item=rows.get(Math.min(index,rows.size()-1));gradient(c,new RectF(716,215,1146,height-130),0x99dcedfa,0x669fc0d5,12);float bodyY=254;Bitmap art=ra.image(item.image);if(art!=null){float h=150,w=h*art.getWidth()/art.getHeight();if(w>300){w=300;h=w*art.getHeight()/art.getWidth();}p.setColor(Color.WHITE);c.drawBitmap(art,null,new RectF(748,240,748+w,240+h),p);bodyY=270+h;}wrapped(c,item.body,744,bodyY,370,24,height-150);}
    gradient(c,new RectF(100,height-104,1180,height+20),0xff82afcc,0xffbdd8e8,20);button(c,150,height-45,"A","Select",0xff7eaf3c);button(c,330,height-45,"B","Back",0xffbb4436);button(c,490,height-45,"Y","Refresh",0xffd2b747);button(c,710,height-45,"X","Settings",0xff368dc2);text(c,fit(ra.status,1000,18),135,height-78,18,0xff294f6a);c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){float x=(e.getX()-left)/scale,y=e.getY()/scale;if(e.getAction()==0){down=y;return true;}if(e.getAction()!=1)return true;if(Math.abs(y-down)>45){move(y<down?slots():-slots());return true;}if(y>height-65){if(x<290)select();else if(x<440)back();else if(x<680)ra.refresh();else page(4);return true;}if(x<110){back();return true;}if(x<680&&y>=215){int n=offset+(int)((y-215)/61);if(n<rows.size()&&n<offset+slots()){if(n==index)select();else{index=n;invalidate();}}}return true;}
}
